@Component("collateral-handler")
@ProcessingGroup("collateral-processing-group")
public class CollateralEventHandler {
	
	// core constructor
	CollateralEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCollateralEvent
     */
    @EventHandler
    public void handle( CreateCollateralEvent event) {
        entityManager.persist(new Collateral(event.getCollateralId(), event.getDescription(), event.getValue(), event.getLoan(), event.getCollateralType()));
    }

    /*
     * @param	event UpdateCollateralEvent
     */
    @EventHandler
    public Collateral handle( UpdateCollateralEvent event) {
    	entityManager.merge(new Collateral(event.getCollateralId(), event.getDescription(), event.getValue(), event.getLoan(), event.getCollateralType()));
    }
    
    /*
     * @param	event DeleteCollateralEvent
     */
    @EventHandler
    public void on( DeleteCollateralEvent event) {
    	Collateral entity = new Collateral();
   
    	// ------------------------------------------
    	// apply the CollateralId
    	// ------------------------------------------
    	entity.setCollateralId( event.getCollateralId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CollateralRepository collateralEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CollateralEventHandler.class.getName());

}
